import {roots,parts,blooms,questions,discoveryInvitation} from './word-garden-content.mjs';
import {wordState,resultFor,pairId,chooseBase,choosePart,tryWord,replayWord,addAnotherPart,chooseQuestion,nextQuestion,discussWord} from './word-garden-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plant=(bloom=false)=>`<svg class="word-plant" viewBox="0 0 180 170" aria-hidden="true"><path d="M20 153q70-14 140 0" fill="none" stroke="#abc4da" stroke-width="7"/><path d="m49 117 12 43h58l12-43Z" fill="#b4a6c8" stroke="#183f39" stroke-width="3"/><path d="M90 117V41m0 53Q36 57 44 87q9 24 46 7m0-21q53-37 45-7q-9 21-45 7" stroke="#397958" stroke-width="4" fill="#90b9ae"/>${bloom?'<g fill="#e9b84a" stroke="#183f39" stroke-width="2"><ellipse cx="90" cy="35" rx="13" ry="23"/><ellipse cx="90" cy="35" rx="13" ry="23" transform="rotate(60 90 35)"/><ellipse cx="90" cy="35" rx="13" ry="23" transform="rotate(120 90 35)"/><circle cx="90" cy="35" r="10" fill="#fffef9"/></g>':'<path d="M90 45Q63 16 90 12q27 4 0 33" fill="#abc4da" stroke="#183f39" stroke-width="2"/>'}</svg>`;
function sceneArt(kind){
 const pictures={
 library:'<path d="M19 72V22h102v50M64 22v50M26 31h30m-30 14h30m-30 14h30m19-28h32m-32 14h32m-32 14h32"/>',
 bridge:'<path d="M9 65q60-65 122 0M20 70V41m23 29V27m25 43V20m25 50V27m24 43v29M9 76q15-13 30 0t30 0t30 0t30 0"/>',
 basket:'<path d="m29 36 10 38h63l10-38ZM44 36Q70-7 97 36M45 48h50M49 60h43m-29-24v38m16-38v38"/>',
 sign:'<path d="M69 83V18m0 1h48v29H69M16 24h47v28H16"/><path d="m27 38 8 7 15-19m29 4h25m-25 8h18"/>',
 tea:'<path d="M35 29h59v30q-30 22-59 0Zm59 5q36-3 13 24H94M24 78h88M50 19q-13-10 0-17m18 17q-13-10 0-17"/>',
 bell:'<path d="M44 49V32q0-37 42-12q10 8 10 29l13 13H31ZM59 70q13 20 25 0M67 6V0m-45 23-13-8m107 8 13-8"/>'
 };
 return `<svg class="word-scene" viewBox="0 0 140 90" aria-hidden="true"><g fill="none" stroke="#183f39" stroke-width="4" stroke-linecap="round" stroke-linejoin="round">${pictures[kind]||pictures.sign}</g></svg>`;
}
function construction(base,part){const p=parts.find(p=>p.id===part);return `<span class="word-construction">${p.position==='front'?`<span class="word-cutting">${esc(p.label)}</span><span>+</span><span class="word-base">${esc(base)}</span>`:`<span class="word-base">${esc(base)}</span><span>+</span><span class="word-cutting">${esc(p.label)}</span>`}</span>`;}
function resultPanel(w){
 const r=resultFor(w.draft.result);if(!r)return `<section class="word-result word-empty"><div>${plant()}</div><div><h2>A little room for a new idea</h2><p>Pick a word plant and a cutting. Then try them together.</p><p>Some combinations grow familiar words. Others give us something to wonder about.</p></div></section>`;
 const known=r.kind!=='wonder',title=r.kind==='bloom'?'A word in bloom':known?'Another real word':'A word to wonder about';
 return `<section class="word-result ${r.kind==='bloom'?'word-bloom':'word-discovery'}" aria-labelledby="word-result-title"><div>${plant(r.kind==='bloom')}</div><div><p class="word-result-kind">${title}</p><h2 id="word-result-title" tabindex="-1">${known?esc(r.word):'What could these parts mean?'}</h2><p>${construction(r.base,r.part)}${known?`<span class="word-yields"> makes <strong>${esc(r.word)}</strong></span>`:'<span class="word-yields"> (a letter experiment)</span>'}</p>${known?`<p class="word-meaning">${esc(r.meaning)}.</p>${r.note?`<p>${esc(r.note)}</p>`:''}<div class="word-story">${sceneArt(r.art)}<p>${esc(r.scene)}</p></div>${hearButton(`${r.word}. ${r.meaning}. ${r.scene}${r.note?' '+r.note:''}`,'Hear this word and scene')}`:`<p>${esc(discoveryInvitation)}</p>${hearButton(discoveryInvitation,'Hear our discovery invitation')}`}<p class="word-wonder">Dot wonders: ${known?'Where could you use this word in your own story?':'Could your word belong on a sign, in a café order, or in a story?'}</p>${r.word==='helpful'?'<button class="secondary" data-word-more>Add another part</button>':''}${r.word==='unhelpful'?'<p class="word-two">help + -ful → helpful<br>un- + helpful → unhelpful</p>':''}</div></section>`;
}
export function wordGardenPage(state){
 const w=wordState(state);if(!w)return `<div class="page-heading"><a class="back" href="#home"><span aria-hidden="true">←</span> Back to the garden</a><h1>Word Garden</h1><a class="secondary" href="#words/props">Visit the Prop Box</a><a class="secondary" href="#words/endings">Make parcel labels: one and more than one</a><p>This notebook uses a format this version cannot read. Its saved work is kept. <a href="#notes">Download your notes</a> before changing versions.</p></div>`;
 const d=w.draft,p=parts.find(p=>p.id===d.part),q=questions.find(q=>q.id===d.questionId),pairs=[...w.grown.map(id=>{const b=blooms.find(x=>x.id===id);return pairId(b.base,b.part);}),...w.discoveries];
 return `<div class="word-garden"><div class="page-heading"><a class="back" href="#home"><span aria-hidden="true">←</span> Back to the garden</a><h1>Word Garden</h1><a class="secondary" href="#words/props">Visit the Prop Box</a><a class="secondary" href="#words/endings">Make parcel labels: one and more than one</a><p>The storm scattered the library signs. Behind the library, words are growing again. Choose a plant, add a cutting, and bring your own ideas.</p>${hearButton('The storm scattered the library signs. Behind the library, words are growing again. Choose a word plant, then a cutting. Some combinations grow familiar words. Others give us something to wonder about.','Hear how to play')}</div><section class="word-bench" aria-label="Word potting bench"><div class="word-tools"><fieldset class="word-roots"><legend>Choose a word plant</legend><div class="word-root-grid">${roots.map(base=>`<button class="word-root ${d.base===base?'selected':''}" data-word-base="${base}" aria-pressed="${d.base===base}"><span aria-hidden="true">♧</span><span>${base}</span></button>`).join('')}${w.grown.includes('helpful')?`<button class="word-root ${d.base==='helpful'?'selected':''}" data-word-base="helpful" aria-pressed="${d.base==='helpful'}"><span aria-hidden="true">✿</span><span>helpful</span></button>`:''}</div></fieldset><fieldset class="word-parts"><legend>Choose a cutting</legend><div class="word-part-grid">${parts.map(c=>`<button class="word-part ${d.part===c.id?'selected':''}" data-word-part="${c.id}" aria-pressed="${d.part===c.id}" aria-label="${esc(c.label)}, goes at the ${c.position==='front'?'front':'end'}">${esc(c.label)}<span>${c.position==='front'?'front':'end'}</span></button>`).join('')}</div><p class="word-part-meaning">${esc(p.meaning)}</p>${hearButton(p.meaning,'Hear what this cutting does')}</fieldset></div><div class="word-ready">${construction(d.base,d.part)}<button class="primary" data-word-try>Try this combination</button></div><p class="word-permission">Every combination is welcome. There is no hurry.</p></section>${resultPanel(w)}<section class="word-notebook"><h2>Our word notebook</h2><p>Words and discoveries we have met. Tap one to explore it again.</p>${pairs.length?`<div class="word-labels">${pairs.map(id=>{const r=resultFor(id);return `<button class="secondary" data-word-replay="${id}">${r.kind==='bloom'?'✿':'❧'} ${r.word?esc(r.word):construction(r.base,r.part)}</button>`;}).join('')}</div>`:'<p>Your first combination will have a place here, whether it blooms or makes us wonder.</p>'}</section><section class="word-discussion" aria-labelledby="word-question-title"><h2>Wondering with Dot</h2><p>Try a new sentence or invent a meaning together. Every wondering is open.</p><label for="word-question-picker">Choose a wondering</label><select id="word-question-picker">${questions.map(x=>`<option value="${x.id}" ${x.id===q.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><h3 id="word-question-title" tabindex="-1">${esc(q.prompt)}</h3>${hearButton(q.prompt,'Hear this wondering')}<div class="word-answer-choices">${q.choices.map((c,i)=>`<button class="secondary ${d.choice===i?'selected':''}" data-word-discuss="${i}" aria-pressed="${d.choice===i}">${esc(c)}</button>`).join('')}</div>${d.choice!==null?`<div class="word-thought" role="status"><p>${esc(q.explanation)}</p>${hearButton(q.explanation,'Hear an idea to discuss')}</div>`:''}<button class="text-button" data-word-next>Another wondering</button><p class="tiny">Talk, act it out, or draw. These choices are invitations to discuss.</p></section><aside class="word-away"><h2>A word can travel</h2><p>Could a new word help you tell a story or understand a message?</p><a class="secondary" href="#paris">Find a Paris story</a> <a class="text-button" href="#explore">Follow another curiosity</a></aside></div>`;
}
export function wordGardenNotes(state){
 if(!Object.hasOwn(state,'words'))return '';const w=wordState(state);if(!w)return '<section class="panel"><h2>Word Garden</h2><p>Unsupported notebook kept unchanged in the notes download. Word Garden actions are paused.</p></section>';
 return `<details class="panel"><summary>Word Garden: encounters and wondering</summary><p>Explored with any amount of help. These records do not establish independent reading, spelling, decoding or transfer.</p><p>Blooms encountered: ${w.grown.map(esc).join(', ')||'none yet'}.</p><p>Other combinations: ${w.discoveries.map(id=>{const r=resultFor(id);return esc(r.word||`${r.base} with ${r.cutting.label}`);}).join(', ')||'none yet'}.</p><p>Discussion cards visited: ${w.seen.map(id=>esc(questions.find(q=>q.id===id).title)).join(', ')||'none yet'}.</p><a href="#words">Visit Word Garden</a></details>`;
}
export function bindWordGarden(state,{save,render,focus}){
 const act=(fn,target)=>{if(fn()){save();render();if(target)focus?.(target);}};
 document.querySelectorAll('[data-word-base]').forEach(b=>b.onclick=()=>act(()=>chooseBase(state,b.dataset.wordBase),`[data-word-base="${b.dataset.wordBase}"]`));
 document.querySelectorAll('[data-word-part]').forEach(b=>b.onclick=()=>act(()=>choosePart(state,b.dataset.wordPart),`[data-word-part="${b.dataset.wordPart}"]`));
 document.querySelector('[data-word-try]')?.addEventListener('click',()=>act(()=>tryWord(state),'#word-result-title'));
 document.querySelectorAll('[data-word-replay]').forEach(b=>b.onclick=()=>act(()=>replayWord(state,b.dataset.wordReplay),'#word-result-title'));
 document.querySelector('[data-word-more]')?.addEventListener('click',()=>act(()=>addAnotherPart(state),'[data-word-base="helpful"]'));
 document.querySelector('#word-question-picker')?.addEventListener('change',e=>act(()=>chooseQuestion(state,e.target.value),'#word-question-title'));
 document.querySelectorAll('[data-word-discuss]').forEach(b=>b.onclick=()=>act(()=>discussWord(state,Number(b.dataset.wordDiscuss)),`[data-word-discuss="${b.dataset.wordDiscuss}"]`));
 document.querySelector('[data-word-next]')?.addEventListener('click',()=>act(()=>nextQuestion(state),'#word-question-title'));
}
